using BARANG.Core.Application.Abstractions.Actors;
using BARANG.Core.Application.Abstractions.Companies;
using BARANG.Core.Application.Abstractions.Transactions;
using BARANG.Core.Application.Auditing;
using BARANG.Core.Application.BusinessAnalysis;
using BARANG.Core.Domain.Auditing;
using BARANG.Core.Domain.BusinessAnalysis;
using BARANG.Core.Domain.Common;
using BARANG.Core.Domain.Customers;
using BARANG.Core.Domain.Orders;
using BARANG.Core.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;

namespace BARANG.Core.Infrastructure.BusinessAnalysis;

public sealed class BusinessProfileAdministration(CoreDbContext db,ITransactionExecutor tx,ICompanyContext company,IAuditWriter audit,TimeProvider time):IBusinessProfileAdministration
{
    private Guid Company=>company.RequireCompanyId();private DateTimeOffset Now=>time.GetUtcNow();
    public Task<Result<CustomerBusinessProfileView>>GetCustomerAsync(Guid id,CancellationToken ct)=>tx.ExecuteAsync(async t=>{var x=await db.CustomerBusinessProfiles.AsNoTracking().SingleOrDefaultAsync(p=>p.CustomerId==id,t);return x is null?Result.Failure<CustomerBusinessProfileView>(BusinessProfileErrors.NotFound):Result.Success(View(x));},ct);
    public Task<Result<CustomerBusinessProfileView>>SetCustomerAsync(Guid id,CustomerBusinessProfileCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{Customer?customer=await db.Customers.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id,t);if(customer is null||customer.CustomerType==CustomerType.Organization&&c.DateOfBirth is not null)return Result.Failure<CustomerBusinessProfileView>(BusinessProfileErrors.ParentInvalid);var x=await db.CustomerBusinessProfiles.SingleOrDefaultAsync(p=>p.CustomerId==id,t);if(x is null){var made=CustomerBusinessProfile.Create(Company,id,c.DateOfBirth,c.EconomicCode,c.CreditLimit,c.PaymentTermsDays,c.BusinessDetails,Now);if(made.IsFailure)return Result.Failure<CustomerBusinessProfileView>(made.Error);x=made.Value;db.Add(x);}else{Result r=x.Update(c.DateOfBirth,c.EconomicCode,c.CreditLimit,c.PaymentTermsDays,c.BusinessDetails,c.Version,Now);if(r.IsFailure)return Result.Failure<CustomerBusinessProfileView>(r.Error);}Log("customer.business_profile.updated",x.Id);return Result.Success(View(x));},ct);
    public Task<Result<ProductTechnicalProfileView>>GetProductAsync(Guid id,Guid?variant,CancellationToken ct)=>tx.ExecuteAsync(async t=>{var x=await db.ProductTechnicalProfiles.AsNoTracking().SingleOrDefaultAsync(p=>p.ProductId==id&&p.ProductVariantId==variant,t);return x is null?Result.Failure<ProductTechnicalProfileView>(BusinessProfileErrors.NotFound):Result.Success(View(x));},ct);
    public Task<Result<ProductTechnicalProfileView>>SetProductAsync(Guid id,ProductTechnicalProfileCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{if(!await db.Products.AnyAsync(x=>x.Id==id,t)||c.ProductVariantId is Guid v&&!await db.ProductVariants.AnyAsync(x=>x.Id==v&&x.ProductId==id,t))return Result.Failure<ProductTechnicalProfileView>(BusinessProfileErrors.ParentInvalid);var x=await db.ProductTechnicalProfiles.SingleOrDefaultAsync(p=>p.ProductId==id&&p.ProductVariantId==c.ProductVariantId,t);if(x is null){var made=ProductTechnicalProfile.Create(Company,id,c.ProductVariantId,c.BrandCode,c.MaterialCode,c.GenderCode,c.FitCode,c.StyleCode,c.TechnicalAttributes,Now);if(made.IsFailure)return Result.Failure<ProductTechnicalProfileView>(made.Error);x=made.Value;db.Add(x);}else{Result r=x.Update(c.BrandCode,c.MaterialCode,c.GenderCode,c.FitCode,c.StyleCode,c.TechnicalAttributes,c.Version,Now);if(r.IsFailure)return Result.Failure<ProductTechnicalProfileView>(r.Error);}Log("product.technical_profile.updated",x.Id);return Result.Success(View(x));},ct);
    public Task<Result<OrderBusinessProfileView>>GetOrderAsync(Guid id,CancellationToken ct)=>tx.ExecuteAsync(async t=>{var x=await db.OrderBusinessProfiles.AsNoTracking().SingleOrDefaultAsync(p=>p.OrderId==id,t);return x is null?Result.Failure<OrderBusinessProfileView>(BusinessProfileErrors.NotFound):Result.Success(View(x));},ct);
    public Task<Result<OrderBusinessProfileView>>SetOrderAsync(Guid id,OrderBusinessProfileCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{Order?order=await db.Orders.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id,t);if(order is null||order.Status!=OrderStatus.Draft)return Result.Failure<OrderBusinessProfileView>(BusinessProfileErrors.ParentInvalid);var x=await db.OrderBusinessProfiles.SingleOrDefaultAsync(p=>p.OrderId==id,t);if(x is null){var made=OrderBusinessProfile.Create(Company,id,c.ShippingMethodCode,c.PackagingTypeCode,c.IncludeInvoiceInPackage,c.OrderTypeCode,c.Notes,Now);if(made.IsFailure)return Result.Failure<OrderBusinessProfileView>(made.Error);x=made.Value;db.Add(x);}else{Result r=x.Update(c.ShippingMethodCode,c.PackagingTypeCode,c.IncludeInvoiceInPackage,c.OrderTypeCode,c.Notes,c.Version,Now);if(r.IsFailure)return Result.Failure<OrderBusinessProfileView>(r.Error);}Log("order.business_profile.updated",x.Id);return Result.Success(View(x));},ct);
    public Task<Result<PrintTechnicalProfileView>>GetPrintAsync(Guid id,CancellationToken ct)=>tx.ExecuteAsync(async t=>{var x=await db.PrintTechnicalProfiles.AsNoTracking().SingleOrDefaultAsync(p=>p.OrderPrintOperationId==id,t);return x is null?Result.Failure<PrintTechnicalProfileView>(BusinessProfileErrors.NotFound):Result.Success(View(x));},ct);
    public Task<Result<PrintTechnicalProfileView>>SetPrintAsync(Guid id,PrintTechnicalProfileCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{var operation=await db.OrderPrintOperations.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id&&x.IsActive,t);if(operation is null||!await db.Orders.AnyAsync(x=>x.Id==operation.OrderId&&x.Status==OrderStatus.Draft,t))return Result.Failure<PrintTechnicalProfileView>(BusinessProfileErrors.ParentInvalid);if(c.PrinterEquipmentId is Guid printer&&!await CompatibleEquipment(printer,true,t)||c.HeatPressEquipmentId is Guid press&&!await CompatibleEquipment(press,false,t))return Result.Failure<PrintTechnicalProfileView>(BusinessProfileErrors.ParentInvalid);var x=await db.PrintTechnicalProfiles.SingleOrDefaultAsync(p=>p.OrderPrintOperationId==id,t);if(x is null){var made=PrintTechnicalProfile.Create(Company,id,c.DirectionCode,c.PrintSizeCode,c.PrintCount,c.PrinterEquipmentId,c.HeatPressEquipmentId,c.Specifications,Now);if(made.IsFailure)return Result.Failure<PrintTechnicalProfileView>(made.Error);x=made.Value;db.Add(x);}else{Result r=x.Update(c.DirectionCode,c.PrintSizeCode,c.PrintCount,c.PrinterEquipmentId,c.HeatPressEquipmentId,c.Specifications,c.Version,Now);if(r.IsFailure)return Result.Failure<PrintTechnicalProfileView>(r.Error);}Log("order.print.technical_profile.updated",x.Id);return Result.Success(View(x));},ct);
    private async Task<bool>CompatibleEquipment(Guid id,bool printer,CancellationToken ct){var e=await db.Equipment.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id&&x.IsActive,ct);if(e is null||e.OperationalStatusCode is not("AVAILABLE" or "READY"))return false;return printer?e.EquipmentTypeCode.Contains("PRINT",StringComparison.OrdinalIgnoreCase):e.EquipmentTypeCode.Contains("HEAT",StringComparison.OrdinalIgnoreCase)||e.EquipmentTypeCode.Contains("PRESS",StringComparison.OrdinalIgnoreCase);}
    private void Log(string action,Guid id)=>audit.Write(new(action,"business_profile",id.ToString(),ChangeKind:AuditChangeKind.Modified));
    private static CustomerBusinessProfileView View(CustomerBusinessProfile x)=>new(x.Id,x.CustomerId,x.DateOfBirth,x.EconomicCode,x.CreditLimit,x.PaymentTermsDays,x.BusinessDetails,x.Version);
    private static ProductTechnicalProfileView View(ProductTechnicalProfile x)=>new(x.Id,x.ProductId,x.ProductVariantId,x.BrandCode,x.MaterialCode,x.GenderCode,x.FitCode,x.StyleCode,x.TechnicalAttributes,x.Version);
    private static OrderBusinessProfileView View(OrderBusinessProfile x)=>new(x.Id,x.OrderId,x.ShippingMethodCode,x.PackagingTypeCode,x.IncludeInvoiceInPackage,x.OrderTypeCode,x.Notes,x.Version);
    private static PrintTechnicalProfileView View(PrintTechnicalProfile x)=>new(x.Id,x.OrderPrintOperationId,x.DirectionCode,x.PrintSizeCode,x.PrintCount,x.PrinterEquipmentId,x.HeatPressEquipmentId,x.Specifications,x.Version);
}
